    async function setAnnotationFeedback(on) {
        if (!state.currentProject) return;
        try {
            const p = await api('/projects/' + state.currentProject.id, {
                method: 'PUT',
                body: JSON.stringify({ annotation_feedback: on ? 1 : 0 }),
            });
            state.currentProject = { ...state.currentProject, ...p };
            renderAnnotationFeedbackToggle();
            setStatus(on
                // Said plainly, because it is the part that surprises people: a
                // mark is not consumed by the generation that acts on it.
                ? 'Marks carrying a note now steer this shot\u2019s prompt, and keep doing so until deleted.'
                : 'Marks are notation only again. Nothing in generation reads them.');
            // Every frame's badge is now wrong.
            for (const shotId of Object.keys(MARKUP.cache)) markupPaintAll(shotId);
        } catch (err) {
            setStatus('Could not change that: ' + err.message);
            renderAnnotationFeedbackToggle();
        }
    }

    function renderBoardProtect() {
        const value = (document.getElementById('boardProtectRatio') || {}).value || '';
        const ratios = protectSelection(value);
        const boxes = document.querySelectorAll('.board-protect');
        if (!ratios.length) { boxes.forEach(b => { b.style.display = 'none'; b.innerHTML = ''; }); return; }

        boxes.forEach(box => {
            const img = box.parentNode.querySelector('img');
            if (!img || !img.naturalWidth) { box.style.display = 'none'; return; }
            box.style.display = 'block';
            box.innerHTML = protectOverlayHTML(img.naturalWidth / img.naturalHeight, ratios);
        });
    }
